type ReleaseAction = 'submit-review' | 'review' | 'approve' | 'reject' | 'deploy' | 'rollback' | 'retry' | 'edit';

// LOG_DISPLAY_LIMIT bounds the lines the live log view holds. A line pushed out
// of this buffer is gone from the view, so the reader has to be told - and told
// where it went: the server keeps the whole log, which the download reaches.
export const LOG_DISPLAY_LIMIT = 4999;

// RELEASE_LOG_TRUNCATED_NOTICE leads a copied log the view could not hold whole.
// The lines that went missing are the oldest ones, so the notice belongs at the
// top: a paste that begins mid-deploy otherwise reads as a deploy that began there.
export const RELEASE_LOG_TRUNCATED_NOTICE =
  '[releasedock] 화면 표시 한도를 넘어 앞부분의 오래된 로그가 빠졌습니다. 아래는 마지막 부분만 담고 있습니다.';

export interface ReleaseLogState {
  lines: LogEntry[];
  truncated: boolean;
}

// appendReleaseLogLine trims and records the loss in one step, so the flag can
// never disagree with the buffer it describes. Reaching the limit exactly is not
// truncation; only a line actually pushed out is.
export function appendReleaseLogLine(state: ReleaseLogState, entry: LogEntry, limit = LOG_DISPLAY_LIMIT): ReleaseLogState {
  const lines = [...state.lines, entry];
  const dropped = lines.length > limit;
  return { lines: dropped ? lines.slice(lines.length - limit) : lines, truncated: state.truncated || dropped };
}

export const EMPTY_RELEASE_LOGS: ReleaseLogState = { lines: [], truncated: false };

function useReleaseLogs(releaseId: string | undefined, enabled: boolean) {
  const [logs, setLogs] = useState<ReleaseLogState>(EMPTY_RELEASE_LOGS);
  const [connected, setConnected] = useState(false);
  const [streamLost, setStreamLost] = useState(false);
  const sequence = useRef(0);
  const cursor = useRef(0);
  const [streamAttempt, setStreamAttempt] = useState(0);

  useEffect(() => {
    // Another release must start empty; a timeout resume keeps its lines, its
    // truncation notice and never runs this.
    cursor.current = 0;
    setLogs(EMPTY_RELEASE_LOGS);
    setConnected(false);
    setStreamLost(false);
  }, [releaseId, enabled]);

  useEffect(() => {
    if (!releaseId || !enabled) return;
    let stopped = false;
    const source = new EventSource(`${api.releaseLogStreamUrl(releaseId)}?after=${cursor.current}`, { withCredentials: true });
    const advanceCursor = (value: unknown) => {
      const id = typeof value === 'string' && /^\d+$/.test(value) ? Number(value) : value;
      if (typeof id === 'number' && Number.isSafeInteger(id) && id > cursor.current) cursor.current = id;
    };
    source.onopen = () => {
      setConnected(true);
      setStreamLost(false);
    };
    const receiveLog = (rawEvent: Event) => {
      if (stopped) return;
      const event = rawEvent as MessageEvent<string>;
      advanceCursor(event.lastEventId);
      let entry: Omit<LogEntry, 'id'>;
      try {
        const parsed = JSON.parse(event.data) as Partial<LogEntry> & { createdAt?: string; stream?: string; data?: Partial<LogEntry> & { createdAt?: string; stream?: string } };
        const value = parsed.data ?? parsed;
        advanceCursor(value.id);
        entry = {
          timestamp: value.timestamp ?? value.createdAt,
          level: value.level ?? value.stream,
          step: value.step,
          message: value.message || event.data,
        };
      } catch {
        entry = { message: event.data };
      }
      // Read the row number here, not inside the updater: React runs queued
      // updaters at flush time, where a whole batch would read the same value
      // and hand every row of it the same key.
      const id = (sequence.current += 1);
      setLogs((current) => appendReleaseLogLine(current, { ...entry, id }));
    };
    source.onmessage = receiveLog;
    source.addEventListener('log', receiveLog);
    source.addEventListener('end', (rawEvent) => {
      if (stopped) return;
      stopped = true;
      setConnected(false);
      source.close();
      try {
        const value = JSON.parse((rawEvent as MessageEvent<string>).data);
        // Full-mode completion is {}; only the server time limit resumes.
        if (value?.reason === 'max_duration') setStreamAttempt((current) => current + 1);
      } catch {
        // Unknown end frames must not start an automatic reconnect loop.
      }
    });
    source.onerror = () => {
      setConnected(false);
      // The browser fires error both when it is about to retry on its own
      // (CONNECTING) and when it has given the stream up (CLOSED); only the
      // second leaves the log stopped for good. It also fires after the end
      // frame closed the stream here, where readyState is CLOSED too but
      // nothing was lost - hence the stopped guard.
      if (!stopped && streamDisconnected(source.readyState)) setStreamLost(true);
    };
    return () => {
      stopped = true;
      source.close();
    };
